class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def insert(node, value):
    if node is None:
        return Node(value)
    if value < node.value:
        node.left = insert(node.left, value)
    elif value > node.value:
        node.right = insert(node.right, value)
    return node


def build(values):
    root = None
    for v in values:
        root = insert(root, v)
    return root


def by_levels(values):
    root = build(values)
    levels = []
    current = [root] if root else []
    while current:
        levels.append([node.value for node in current])
        nxt = []
        for node in current:
            if node.left:
                nxt.append(node.left)
            if node.right:
                nxt.append(node.right)
        current = nxt
    return levels

